/**
 * POST /api/v3/webhooks/{webhookId}/duplicate — clone a webhook.
 */
import { ZId } from "@formbricks/types/common";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { duplicateWebhook } from "@/modules/integrations/webhooks/lib/webhook";
import { getWebhook } from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { getOrganizationIdFromWebhookId, getWorkspaceIdFromWebhookId } from "@/lib/utils/helper";
import { assertCan } from "@/lib/authorization";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { capturePostHogEvent } from "@/lib/posthog";
import { ResourceNotFoundError } from "@formbricks/types/errors";

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "created",
  targetType: "webhook",
  schemas: { params: ZId },
  handler: async ({ parsedInput, authentication, auditLog, requestId, instance }) => {
    const webhookId = parsedInput.params.id;
    const { organizationId, workspaceId } = await Promise.all([
      getOrganizationIdFromWebhookId(webhookId),
      getWorkspaceIdFromWebhookId(webhookId),
    ]);

    await assertCan({ type: "user", id: authentication.userId }, "workspace.write", {
      type: "workspace",
      id: workspaceId,
    });

    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

    const existing = await getWebhook(webhookId);
    if (!existing.ok) {
      throw new ResourceNotFoundError("Webhook", webhookId);
    }

    const webhook = await duplicateWebhook(webhookId, existing.data);

    if (auditLog) {
      auditLog.organizationId = organizationId;
      auditLog.newObject = { ...existing.data };
    }

    capturePostHogEvent(
      authentication.userId,
      "integration_connected",
      {
        integration_type: "webhook",
        organization_id: organizationId,
        workspace_id: workspaceId,
      },
      { organizationId, workspaceId }
    );

    return new Response(
      JSON.stringify({ data: webhook }),
      { status: 201, headers: { "Content-Type": "application/json" } }
    );
  },
});

import { Webhook } from "@formbricks/database/prisma-browser";
import { parseV3ApiError } from "@/modules/api/lib/v3-client";

const JSON_HEADERS = { "Content-Type": "application/json" };

export async function duplicateWebhookApi(webhookId: string): Promise<Webhook> {
  const response = await fetch(`/api/v3/webhooks/${webhookId}/duplicate`, {
    method: "POST",
    cache: "no-store",
    headers: JSON_HEADERS,
  });

  if (!response.ok) {
    throw await parseV3ApiError(response);
  }

  const body = (await response.json()) as { data: Webhook };
  return body.data;
}

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Webhook } from "@formbricks/database/prisma-browser";
import { duplicateWebhookApi } from "../lib/api-client";
import { webhookKeys } from "../lib/query";

export const useDuplicateWebhook = () => {
  const queryClient = useQueryClient();

  return useMutation<Webhook, Error, { webhookId: string; workspaceId: string }>({
    mutationFn: ({ webhookId }) => duplicateWebhookApi(webhookId),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: webhookKeys.lists(variables.workspaceId) });
    },
  });
};

import type { Webhook } from "@formbricks/database/prisma-browser";

export const webhookKeys = {
  all: ["webhooks"] as const,
  lists: (workspaceId: string) => [...webhookKeys.all, "list", workspaceId] as const,
  details: () => [...webhookKeys.all, "detail"] as const,
  detail: (webhookId: string) => [...webhookKeys.details(), webhookId] as const,
};

export function removeWebhookFromList(
  data: Webhook[] | undefined,
  webhookId: string
): Webhook[] | undefined {
  if (!data) return data;
  return data.filter((w) => w.id !== webhookId);
}

"use client";

import { TFunction } from "i18next";
import { useTranslation } from "react-i18next";
import { CopyIcon } from "lucide-react";
import { Webhook } from "@formbricks/database/prisma-browser";
